1	# Detached worker: fetch Claude Code release tag + key official docs, diff against
2	# cached SHA256, append change notes to D:\.claude\docs-updates.md.
3	# No auto-edits to CLAUDE.md / AGENTS.md — surface only, user decides.
4	
5	$ErrorActionPreference = 'SilentlyContinue'
6	
7	[Net.ServicePointManager]::SecurityProtocol = `
8	    [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
9	
10	$cacheDir = 'D:\.claude\.docs-cache'
11	$updatesFile = 'D:\.claude\docs-updates.md'
12	$today = Get-Date -Format 'yyyy-MM-dd'
13	$changes = @()
14	
15	function Save-Hash {
16	    param([string]$path, [string]$value)
17	    Set-Content -Path $path -Value $value -Encoding UTF8
18	}
19	
20	function Get-CachedHash {
21	    param([string]$path)
22	    if (Test-Path $path) { return (Get-Content $path -Raw).Trim() }
23	    return ''
24	}
25	
26	function Get-ContentHash {
27	    param([byte[]]$bytes)
28	    $sha = [Security.Cryptography.SHA256]::Create()
29	    $hash = [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-', '')
30	    $sha.Dispose()
31	    return $hash
32	}
33	
34	# 1. Claude Code CLI release tag
35	try {
36	    $headers = @{ 'User-Agent' = 'claude-code-docs-watcher' }
37	    $rel = Invoke-RestMethod 'https://api.github.com/repos/anthropics/claude-code/releases/latest' `
38	        -Headers $headers -TimeoutSec 8
39	    $tagFile = Join-Path $cacheDir 'release-tag.txt'
40	    $cached = Get-CachedHash $tagFile
41	    if ($rel.tag_name -and $rel.tag_name -ne $cached) {
42	        if ($cached -ne '') {
43	            $changes += "- **Claude Code release**: $($rel.tag_name) (was: $cached) — $($rel.html_url)"
44	        }
45	        Save-Hash $tagFile $rel.tag_name
46	    }
47	} catch { }
48	
49	# 2. Key official docs (SHA256 diff)
50	$docs = @(
51	    @{ name = 'memory';          url = 'https://code.claude.com/docs/en/memory.md' }
52	    @{ name = 'hooks';           url = 'https://code.claude.com/docs/en/hooks.md' }
53	    @{ name = 'best-practices';  url = 'https://code.claude.com/docs/en/best-practices.md' }
54	    @{ name = 'settings';        url = 'https://code.claude.com/docs/en/settings.md' }
55	    @{ name = 'context-window';  url = 'https://code.claude.com/docs/en/context-window.md' }
56	)
57	
58	foreach ($doc in $docs) {
59	    try {
60	        $resp = Invoke-WebRequest $doc.url -TimeoutSec 8 -UseBasicParsing
61	        if ($resp.StatusCode -ne 200) { continue }
62	        $hash = Get-ContentHash $resp.Content
63	        $hashFile = Join-Path $cacheDir "$($doc.name).sha256"
64	        $cached = Get-CachedHash $hashFile
65	        if ($hash -ne $cached) {
66	            if ($cached -ne '') {
67	                $changes += "- **Doc updated**: $($doc.name) — $($doc.url)"
68	            }
69	            Save-Hash $hashFile $hash
70	        }
71	    } catch { }
72	}
73	
74	if ($changes.Count -gt 0) {
75	    $entry = "## $today`n" + ($changes -join "`n") + "`n"
76	    if (-not (Test-Path $updatesFile)) {
77	        $header = "# Claude Code Upstream Updates`n`nAuto-generated by SessionStart hook. Review and decide what to apply.`n`n"
78	        Set-Content -Path $updatesFile -Value ($header + $entry) -Encoding UTF8
79	    } else {
80	        Add-Content -Path $updatesFile -Value $entry -Encoding UTF8
81	    }
82	}
83	
84	exit 0
85	

